"""Build a self-contained local overview from the four finalized Archify HTML files."""
from pathlib import Path
import json
R=Path(__file__).resolve().parent.parent
pages={stem:(R/f'{stem}.html').read_text() for stem in ('01_system','02_ros2','03_erd','04_flow')}
payload=json.dumps(pages,ensure_ascii=False).replace('</','<\\/')
template='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark light"><title>VOSS · Architecture Workspace</title><style>
:root{font-family:Inter,"Noto Sans CJK KR",system-ui,sans-serif;color-scheme:dark;--bg:#080d19;--panel:#101a2b;--panel2:#15233a;--border:#263751;--text:#eef4ff;--muted:#98abc8;--accent:#62d9eb}
:root[data-theme=light]{color-scheme:light;--bg:#f1f5fa;--panel:#fff;--panel2:#eaf0f7;--border:#ccd8e8;--text:#142338;--muted:#50647d;--accent:#006d8a}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text)}button,a{font:inherit}a{color:var(--accent)}.shell{display:grid;grid-template-columns:255px minmax(0,1fr);min-height:100vh}.sidebar{background:var(--panel);border-right:1px solid var(--border);padding:28px 16px;display:flex;flex-direction:column;gap:18px}.brand{padding:0 12px}.eyebrow{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--accent);font-weight:700}.brand h1{font-size:26px;margin:7px 0 4px;letter-spacing:-.04em}.brand p{color:var(--muted);font-size:12px;margin:0}.nav{display:grid;gap:9px}.nav button{width:100%;text-align:left;border:1px solid transparent;background:transparent;color:var(--muted);border-radius:13px;padding:13px 14px;cursor:pointer;display:grid;gap:4px;transition:background .18s,border-color .18s}.nav button:hover{background:var(--panel2)}.nav button[aria-current=true]{background:var(--panel2);border-color:var(--accent);color:var(--text)}.nav small{color:var(--muted);font-size:11px}.side-foot{margin-top:auto;padding:0 12px;color:var(--muted);font-size:11px;line-height:1.6}.main{min-width:0;display:flex;flex-direction:column;padding:22px 24px 16px;gap:15px}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:14px}.top h2{margin:5px 0 6px;font-size:25px;letter-spacing:-.03em}.top p{margin:0;color:var(--muted);font-size:13px;max-width:76ch;line-height:1.5}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.action{border:1px solid var(--border);background:var(--panel);color:var(--text);text-decoration:none;padding:9px 12px;border-radius:9px;font-size:12px;cursor:pointer;white-space:nowrap}.action:hover{border-color:var(--accent)}.viewer{position:relative;flex:1;min-height:730px;border:1px solid var(--border);border-radius:16px;overflow:hidden;background:var(--panel)}iframe{position:absolute;inset:0;width:100%;height:100%;border:0;visibility:hidden;opacity:0;pointer-events:none}iframe.active{visibility:visible;opacity:1;pointer-events:auto;z-index:1}.footer{font-size:11px;color:var(--muted);display:flex;gap:16px;flex-wrap:wrap}.footer a{color:inherit}@media(max-width:800px){.shell{grid-template-columns:1fr}.sidebar{border-right:0;border-bottom:1px solid var(--border);padding:16px}.brand h1{font-size:21px}.nav{grid-template-columns:repeat(2,minmax(0,1fr))}.side-foot{display:none}.main{padding:15px}.top{display:block}.actions{margin-top:14px}.viewer{min-height:720px}}@media(max-width:420px){.nav button{padding:10px;font-size:12px}.top h2{font-size:20px}.viewer{min-height:670px}}
</style></head><body><div class="shell"><aside class="sidebar"><div class="brand"><div class="eyebrow">VOSS / SYSTEM MAP</div><h1>Architecture</h1><p>분류 로봇 시스템 · 코드 기반 도면</p></div><nav class="nav" aria-label="다이어그램 선택"><button type="button" data-page="01_system" aria-current="true"><strong>01 · 시스템</strong><small>Web PC · Robot PC 실행 경계</small></button><button type="button" data-page="02_ros2"><strong>02 · ROS 2 통신</strong><small>노드 · Topic · Service · Action</small></button><button type="button" data-page="03_erd"><strong>03 · 데이터 모델</strong><small>PostgreSQL 3개 테이블</small></button><button type="button" data-page="04_flow"><strong>04 · 공정 흐름</strong><small>분류 · 재확인 · 적재</small></button></nav><div class="side-foot">각 도면은 Archify Viewer입니다.<br>노드를 누르면 근거와 세부 정보를 볼 수 있습니다.<br>검색·경로·확대·내보내기는 뷰어 툴바에서 사용하세요.</div></aside><main class="main"><div class="top"><div><div class="eyebrow" id="section">01 / SYSTEM ARCHITECTURE</div><h2 id="title">전체 시스템 아키텍처</h2><p id="desc">Web PC와 Robot PC의 실제 프로세스 실행 위치, SSH 연결과 양방향 반환 흐름을 확인합니다.</p></div><div class="actions"><button class="action" id="theme" type="button">라이트 테마</button><a class="action" id="open" href="01_system.html" target="_blank" rel="noopener">원본 뷰어 열기 ↗</a><a class="action" id="data" href="data/01_system.json">원본 JSON</a></div></div><div class="viewer" id="viewer" aria-label="Archify 도면"><iframe title="전체 시스템 아키텍처" class="active" data-page="01_system"></iframe><iframe title="ROS 2 통신 아키텍처" data-page="02_ros2"></iframe><iframe title="PostgreSQL 데이터 모델" data-page="03_erd"></iframe><iframe title="분류 및 적재 공정 흐름" data-page="04_flow"></iframe></div><div class="footer"><span>VOSS · Archify 3.1.0</span><a href="ANALYSIS.md">코드 근거</a><a href="VALIDATION_SUMMARY.md">검증 결과</a><a href="UNCONFIRMED.md">미확인 사항</a><span>로컬 HTML · 오프라인 열람</span></div></main></div><script>
const pages=__PAGES__;
const info={"01_system":["01 / SYSTEM ARCHITECTURE","전체 시스템 아키텍처","Web PC와 Robot PC의 실제 프로세스 실행 위치, SSH 연결과 양방향 반환 흐름을 확인합니다."],"02_ros2":["02 / ROS 2 COMMUNICATION","ROS 2 통신 아키텍처","Robot PC와 Web PC의 ROS 노드를 분리했습니다. Topic은 발행 방향, Service·Action은 요청과 응답/피드백 방향으로 읽습니다."],"03_erd":["03 / DATABASE ERD","PostgreSQL 데이터 모델","모든 컬럼과 PK, box_id·session_id의 점선 논리 관계와 카디널리티를 표시합니다."],"04_flow":["04 / PROCESS FLOW","분류 · 적재 공정 흐름","판단은 마름모, 운영자 입력은 평행사변형, DB 기록은 원통으로 표시합니다. PAUSED 복구와 수동 종료를 따라갑니다."]};
const frames=[...document.querySelectorAll('iframe[data-page]')];let current='01_system';let light=false;
for(const f of frames){f.srcdoc=pages[f.dataset.page]}
function choose(k){current=k;for(const f of frames)f.classList.toggle('active',f.dataset.page===k);for(const b of document.querySelectorAll('.nav button'))b.setAttribute('aria-current',String(b.dataset.page===k));document.getElementById('section').textContent=info[k][0];document.getElementById('title').textContent=info[k][1];document.getElementById('desc').textContent=info[k][2];document.getElementById('open').href=k+'.html';document.getElementById('data').href='data/'+k+'.json'}
for(const b of document.querySelectorAll('.nav button'))b.addEventListener('click',()=>choose(b.dataset.page));
function syncTheme(f){try{const root=f.contentDocument.documentElement;const isLight=root.dataset.theme==='light';if(isLight!==light)f.contentDocument.getElementById('btn-theme')?.click()}catch(e){console.warn('Viewer theme sync unavailable',e)}}
for(const f of frames)f.addEventListener('load',()=>syncTheme(f));
document.getElementById('theme').addEventListener('click',()=>{light=!light;document.documentElement.dataset.theme=light?'light':'dark';document.getElementById('theme').textContent=light?'다크 테마':'라이트 테마';for(const f of frames)syncTheme(f)});
</script></body></html>'''
html=template.replace('__PAGES__',payload)
for name in ('index.html','site-wrapper.html'):(R/name).write_text(html)
print('built standalone workspace',len(html),'bytes')
